+    // C must be zeroed because we accumulate into it.
+    std::fill(C, C + (size_t)n * n, 0.0f);
+
+    unsigned int num_threads = std::thread::hardware_concurrency();
+    if (num_threads == 0) num_threads = 4;
+    if (n < 256) num_threads = 1;
+    num_threads = std::min(num_threads, (unsigned int)n);
+
+    int chunk = (n + num_threads - 1) / num_threads;
+
+    auto worker = [&](int start_i, int end_i) {
+        for (int i = start_i; i < end_i; ++i) {
+            const float* A_row = A + i * n;
+            float* C_row = C + i * n;
+            for (int k = 0; k < n; ++k) {
+                float a = A_row[k];
+                const float* B_row = B + k * n;
+                int j = 0;
+#if defined(__ARM_NEON)
+                float32x4_t a_vec = vdupq_f32(a);
+                for (; j <= n - 4; j += 4) {
