+    if (num_threads == 1) {
+        worker(0, n);
+    } else {
+        std::vector<std::thread> threads;
+        for (unsigned int t = 0; t < num_threads; ++t) {
+            int start = t * chunk;
+            int end = std::min(start + chunk, n);
+            if (start >= end) break;
+            threads.emplace_back(worker, start, end);
